<script>
  // Тема/язык/вид ДО рендера (ключи общие со SPA: helmer_theme / helmer_lang).
  // Вид чекаута: localStorage helmer_co_layout = compact|wide.
  // ДЛЯ РАЗРАБОВ/МЕРЧАНТОВ: вид можно форсить параметром ?layout=wide|compact
  // (он же сохраняется покупателю) — удобно задать вид ссылкой из магазина.
  (function () {
    try {
      // Форс-тема из ?theme (виджет: сайт мерчанта может быть светлым) имеет
      // приоритет над localStorage. force_theme/embed подставляются сервером;
      // default(...) — чтобы шаблон не падал, если контекст их не передал.
      var forced = null;
      var t = forced || (localStorage.getItem("helmer_theme") === "light" ? "light" : "dark");
      document.documentElement.classList.toggle("dark", t === "dark");
      document.documentElement.classList.toggle("light", t === "light");
      var l = localStorage.getItem("helmer_lang") === "en" ? "en" : "ru";
      document.documentElement.setAttribute("lang", l);
      // Режим виджета: класс на <html> убирает внешние отступы/подсветку.
      if (false) document.documentElement.classList.add("hm-embed");
    } catch (e) {}
  })();
